__global__ void __launch_bounds__(NUM_THREADS) upper_triangular_matmul_kernel(
    const float* __restrict__ A,
    const float* __restrict__ B,
    float* __restrict__ C,
    int N
) {
    // Tensor-core rewrite using an FP32-faithful four-way TF32 decomposition.
    // Each FP32 value x is split as x ~= hi + lo, where both hi and lo are
    // TF32 values. The product uses all four cross-products:
    // hi*hi + hi*lo + lo*hi + lo*lo. This keeps substantially more accuracy
    // than direct TF32 while moving the tile computation to tensor cores.
    // The existing triangular K-range skipping, cp.async multi-stage pipeline,
    // exact boundary masks, and FP32 accumulation/output are preserved.
    __shared__ __align__(128) SharedStorage smem;
    const int tid = threadIdx.x;
    const int warp = tid >> 5;
    const int lane = tid & 31;
    const int warp_m = warp >> 1;
    const int warp_n = warp & 1;
    const int lane_m = lane >> 3;
    const int lane_n = lane & 7;
    const int frag_row = warp_m * WARP_M + lane_m * TM;
    const int frag_col = warp_n * WARP_N + lane_n * TN;
    const int num_tiles = (N + TILE_M - 1) / TILE_M;
    const int bid = blockIdx.x;
    int lo = 0;
    int hi = num_tiles;
    while (hi - lo > 1) {
        const int mid = (lo + hi) >> 1;
        const long start = (long)mid * num_tiles - (long)mid * (mid - 1) / 2;
        if (start <= bid) {
            lo = mid;
        } else {
            hi = mid;
        }
    }
    const int row_tile = lo;
    const long row_start = (long)row_tile * num_tiles - (long)row_tile * (row_tile - 1) / 2;
    const int col_tile = row_tile + (int)(bid - row_start);
    const int tile_m = row_tile * TILE_M;
    const int tile_n = col_tile * TILE_N;
    const bool aligned = ((N & 3) == 0);
#if defined(__CUDA_ARCH__) && (__CUDA_ARCH__ >= 800)
    nvcuda::wmma::fragment<nvcuda::wmma::accumulator, 16, 16, 8, float> acc_frag[2][2];
    #pragma unroll
    for (int i = 0; i < 2; ++i) {
        #pragma unroll
        for (int j = 0; j < 2; ++j) {
            nvcuda::wmma::fill_fragment(acc_frag[i][j], 0.0f);
        }
    }
#else
    float acc[TM][TN];
    #pragma unroll
    for (int i = 0; i < TM; ++i) {
